class Solution {public:string solve(string text,string pattern){if(pattern.empty())return "";vector<int> need(26);for(char c:pattern)need[c-'a']++;int missing=pattern.size(),left=0,start=0,best=INT_MAX;for(int right=0;right<(int)text.size();right++){int c=text[right]-'a';if(need[c]>0)missing--;need[c]--;while(missing==0){if(right-left+1<best){best=right-left+1;start=left;}int old=text[left++]-'a';if(++need[old]>0)missing++;}}return best==INT_MAX?"":text.substr(start,best);}};